scwin.vScrenID = "ULDINS15400.xml";
scwin.cnt = 0;
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 선물옵션 표준코드 관리를 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    /**
     * SrM-000243255 
     */
    if (!scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
        return false;
    }
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS15400_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdFtrOptInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}ISU_NM=" + txb_pISU_NM.getValue() + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue() + "&{P}FUTOPT_UPCLSS_CD=" + scwin.getFutoptUpclssCd() + "&{P}CFI_CD_NULL_YN=" + $c.stf.getObjectValue(ckb_pCFI_CD_NULL_YN) + "&{P}SFI_CD_TYP=" + scwin.getCfCdtyp();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : checkSearchCondition
 * 설명      : SrM-000243255  조회조건을 체크
 *                표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 
 *                날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..
 ***********************************************/
scwin.checkSearchCondition = function() {
    var sStdCd = $c.stf.getObjectValue(txb_pSTD_CD);
    var sIsuKorNm = $c.stf.getObjectValue(txb_pISU_NM);
    var sSDateFrom = $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE); //코드부여일(from)
    var sSDateTo = $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE); //코드부여일(to)

    if (sStdCd == "" && sIsuKorNm == "") {
        if (sSDateFrom == "" && sSDateTo == "") {
            var msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명] 중 1개 이상의 조건을 입력하거나, \n" + "[코드부여일]의 검색기간을 1년 이내로 입력하세요.";
            $c.win.alert(msg);
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom != "" && sSDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sSDateFrom, 1)) < eval(sSDateTo)) {
                $c.win.alert("코드부여일의 검색기간은 1년 이내로 입력하세요.");
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom != "" || sSDateTo != "") {
            $c.win.alert("코드부여일의 검색기간은 1년 이내로 입력하세요.");
            if (sSDateFrom == "") {
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
            } else {
                edt_pSTD_CD_GRNT_DD_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : getFutoptUpclssCd
 * 설명       : 조회를 위한 선물 옵션 유무를 생성한다
 ***********************************************/
scwin.getFutoptUpclssCd = function() {
    var strFutoptUpclssCd = "";
    if ($c.stf.getObjectValue(ckb_FUT_YN) == "Y") strFutoptUpclssCd += "'1'";
    if ($c.stf.getObjectValue(ckb_OPT_YN) == "Y") strFutoptUpclssCd += ((strFutoptUpclssCd.length > 0) ? ",'2'" : "'2'");
    if (strFutoptUpclssCd.length > 0) strFutoptUpclssCd = "(" + strFutoptUpclssCd + ")";
    return strFutoptUpclssCd;
};



/********************************************** 
 * 함수명   : getCfCdtyp
 * 설명       :  조회를 위한 상품선택을 생성한다
 ***********************************************/
scwin.getCfCdtyp = function() {
    var strCFI = "";
    if ($c.stf.getObjectValue(ckb_CFI_CD_11) == "Y") strCFI += "'11'";
    if ($c.stf.getObjectValue(ckb_CFI_CD_12) == "Y") strCFI += ((strCFI.length > 0) ? ",'12'" : "'12'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_13) == "Y") strCFI += ((strCFI.length > 0) ? ",'13'" : "'13'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_21) == "Y") strCFI += ((strCFI.length > 0) ? ",'21'" : "'21'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_22) == "Y") strCFI += ((strCFI.length > 0) ? ",'22'" : "'22'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_31) == "Y") strCFI += ((strCFI.length > 0) ? ",'31'" : "'31'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_32) == "Y") strCFI += ((strCFI.length > 0) ? ",'32'" : "'32'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_33) == "Y") strCFI += ((strCFI.length > 0) ? ",'33'" : "'33'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_34) == "Y") strCFI += ((strCFI.length > 0) ? ",'34'" : "'34'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_35) == "Y") strCFI += ((strCFI.length > 0) ? ",'35'" : "'35'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_41) == "Y") strCFI += ((strCFI.length > 0) ? ",'41'" : "'41'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_42) == "Y") strCFI += ((strCFI.length > 0) ? ",'42'" : "'42'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_43) == "Y") strCFI += ((strCFI.length > 0) ? ",'43'" : "'43'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_44) == "Y") strCFI += ((strCFI.length > 0) ? ",'44'" : "'44'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_51) == "Y") strCFI += ((strCFI.length > 0) ? ",'51'" : "'51'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_52) == "Y") strCFI += ((strCFI.length > 0) ? ",'52'" : "'52'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_47) == "Y") strCFI += ((strCFI.length > 0) ? ",'47'" : "'47'");
    if ($c.stf.getObjectValue(ckb_CFI_CD_99) == "Y") strCFI += ((strCFI.length > 0) ? ",'99'" : "'99'");
    if (strCFI.length > 0) strCFI = "(" + strCFI + ")";
    return strCFI;
};



/********************************************** 
 * 함수명   : setCfCdEnable
 * 설명       : 상품선택 체크박스를 컨트롤 한다
 ***********************************************/
scwin.setCfCdEnable = function(bEnable) {
    ckb_CFI_CD_11.setDisabled(bEnable);
    ckb_CFI_CD_12.setDisabled(bEnable);
    ckb_CFI_CD_13.setDisabled(bEnable);
    ckb_CFI_CD_21.setDisabled(bEnable);
    ckb_CFI_CD_22.setDisabled(bEnable);
    ckb_CFI_CD_31.setDisabled(bEnable);
    ckb_CFI_CD_32.setDisabled(bEnable);
    ckb_CFI_CD_33.setDisabled(bEnable);
    ckb_CFI_CD_34.setDisabled(bEnable);
    ckb_CFI_CD_35.setDisabled(bEnable);
    ckb_CFI_CD_41.setDisabled(bEnable);
    ckb_CFI_CD_42.setDisabled(bEnable);
    ckb_CFI_CD_43.setDisabled(bEnable);
    ckb_CFI_CD_44.setDisabled(bEnable);
    ckb_CFI_CD_51.setDisabled(bEnable);
    ckb_CFI_CD_52.setDisabled(bEnable);
    ckb_CFI_CD_99.setDisabled(bEnable);
    ckb_CFI_CD_47.setDisabled(bEnable);
};



/********************************************** 
 * 함수명   : setCfiCd
 * 설명       : SFI코드를 생성한다
 ***********************************************/
scwin.setCfiCd = function() {
    // 수정기능이 없어져 return 처리 한다 
    return;
    var cfi_cd = "";
    var fut_opt_cd = $c.stf.getObjectValue(cmb_FUTOPT_UPCLSS_CD); // 선물/옵션 구분         
    var f_bs_ass_cd = $c.stf.getObjectValue(cmb_FNC_ULY_TP_CD); // 금융(옵션)기초자산     
    var c_bs_ass_cd = $c.stf.getObjectValue(cmb_PROD_ULY_TP_CD); // 상품기초자산           
    var sttl_mth = $c.stf.getObjectValue(cmb_ELW_SETL_METHD_CD); // 결제방법                 
    var std_yn = $c.stf.getObjectValue(cmb_STD_YN); // 표준화여부              
    var fn_gds_fut_cd = $c.stf.getObjectValue(cmb_FNC_PROD_FUT_TP_CD); // 금융/상품 선물 구분     
    var call_put_cd = $c.stf.getObjectValue(cmb_CALLPUT_TP_CD); // call/put 구분           
    var ame_eur_cd = $c.stf.getObjectValue(cmb_EXER_TP_CD); // 미국식 /유럽식 구분    

    if (txb_pSTD_CD.getValue() == "") {
        return;
    } else if (fut_opt_cd == "1") {
        // 선물 인 경우

        cfi_cd = fut_opt_cd;
        cfi_cd += fn_gds_fut_cd;
        if (fn_gds_fut_cd == "F") {
            cfi_cd += f_bs_ass_cd;
        } else if (fn_gds_fut_cd == "C") {
            cfi_cd += c_bs_ass_cd;
        }
        cfi_cd += sttl_mth;
        cfi_cd += std_yn;
        cfi_cd += "X";
    } else if (fut_opt_cd == "2") {
        // 옵션인 경우  

        cfi_cd = fut_opt_cd;
        cfi_cd += call_put_cd;
        cfi_cd += ame_eur_cd;
        cfi_cd += f_bs_ass_cd;
        cfi_cd += sttl_mth;
        cfi_cd += std_yn;
    }
    txb_CFI_CD.setValue(cfi_cd);
};



/********************************************** 
 * 함수명   : ins_modify	
 * 설명       : 선물옵션 표준코드 관리 수정 한다. screenProcsTpCd 03
 ***********************************************/
scwin.ins_modify = function(mflag) {
    var screenProcsTpCd = "03";
    if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }

        /* CFI 코드 값과 상관없이 수정 되도록 변경 (HSW 요청. 20180605)
        if(txb_CFI_CD.value =="" || txb_CFI_CD.value.indexOf(" ") == "" ) {
        	alert( getMessageParam("MSG-A005", "CFI코드") );
        	txb_CFI_CD.focus();
        	return false;
        }
        */

        if (mflag == "N") return;
        trs_save.Action = "/StdCdFtrOptInfoAction.do?method=modifyStdCdFtrOptInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};


/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    var str_cfi = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
    var temp = $c.stf.getObjectValue(cmb_cb_p_group); //선택된그룹

    //카테고리셋팅
    cfi = str_cfi.substring(0, 1); //카테고리

    //그룹
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_group);

    //1차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);

    //2차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);

    //3차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);

    //4차속성
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    var temp = str_cfi.substring(0, 1); //카테고리

    if (temp == 'F') {
        ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "15", "F", "", "", "G");
    } else if (temp == 'O') {
        ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "16", "O", "", "", "G");
    } else if (temp == 'K') {
        ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "26", "K", "", "", "G");
    } else {
        ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "15", "F", "", "", "G");
    }
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    //PanelToGroupBox(panel_3);
    //PanelToGroupBox(panel_4);

    scwin.setCfCdEnable(false);
    ins_combo_set(dts_FUTOPT_LIST_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03409", "SEL"); // 03409 - 선물옵션상장구분코드
    ins_combo_set(dts_FUTOPT_UPCLSS_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02512", "SEL"); // 02512 - 선물옵션대분류코드
    ins_combo_set(dts_FNC_ULY_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00665", "SEL"); // 00665 - 금융기초자산구분코드
    ins_combo_set(dts_PROD_ULY_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03410", "SEL"); // 03410 - 상품기초자산구분코드
    ins_combo_set(dts_ELW_SETL_METHD_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03430", "SEL"); // 03430 - ELW결제방법코드
    ins_combo_set(dts_FNC_PROD_FUT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03413", "SEL"); // 03413 - 금융상품선물구분코드
    ins_combo_set(dts_CALLPUT_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03414", "SEL"); // 03414 - 콜풋구분코드
    ins_combo_set(dts_EXER_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00055", "SEL"); // 00055 - 권리행사유형코드

    $c.stf.showObj(label_38, false);
    $c.stf.showObj(edt_STD_CD_GRNT_DD, false);
    fn_setFromToDate1("1y", edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(label_39, false);
    $c.stf.showObj(edt_EXP_DD, false);
    $c.stf.showObj(txb_DEL_RSN, false);
    fn_CtrlBtn_temp("no_data");
    txb_pSTD_CD.focus();
};
scwin.btn_prcnm_onclick = function() {
    txb_param1.setValue(txb_STD_CD.getValue()); // 표준코드
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
};
scwin.ckb_FUT_YN_onclick = function() {
    if ($c.stf.getObjectValue(ckb_FUT_YN) == "Y") {
        scwin.setCfCdEnable(true);
    } else {
        if ($c.stf.getObjectValue(ckb_OPT_YN) == "Y" || $c.stf.getObjectValue(ckb_pCFI_CD_NULL_YN) == "Y") {
            scwin.setCfCdEnable(true);
        } else {
            scwin.setCfCdEnable(false);
        }
    }
};
scwin.ckb_OPT_YN_onclick = function() {
    if ($c.stf.getObjectValue(ckb_OPT_YN) == "Y") {
        scwin.setCfCdEnable(true);
    } else {
        if ($c.stf.getObjectValue(ckb_FUT_YN) == "Y" || $c.stf.getObjectValue(ckb_pCFI_CD_NULL_YN) == "Y") {
            scwin.setCfCdEnable(true);
        } else {
            scwin.setCfCdEnable(false);
        }
    }
};
scwin.ckb_pCFI_CD_NULL_YN_onclick = function() {
    if ($c.stf.getObjectValue(ckb_pCFI_CD_NULL_YN) == "Y") {
        scwin.setCfCdEnable(true);
    } else {
        if ($c.stf.getObjectValue(ckb_FUT_YN) == "Y" || $c.stf.getObjectValue(ckb_OPT_YN) == "Y") {
            scwin.setCfCdEnable(true);
        } else {
            scwin.setCfCdEnable(false);
        }
    }
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    fn_SetDisableSelectBtn(btn_search, false);
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    scwin.cnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
