scwin.dts_List_OnRowPosChanged = function(row) {
    if (dts_List.getRowStatus(row) == 1) return;
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn_temp("update");
    var CFI_CD = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
    if (CFI_CD != undefined) {
        scwin.fn_set_Change(CFI_CD);
    }
};
