scwin.cmb_cb_p_group_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_cb_p_group) != "") {
        var str_cfi = dts_List.getCellData(dts_List.getRowPosition(), "CFI_CD");
        var temp1 = str_cfi.substring(0, 1); //카테고리 cfi첫자리
        var temp2 = $c.stf.getObjectValue(cmb_cb_p_group); //선택한 그룹
        var temp3 = '15'; //상품구분코드
        if (temp1 == 'F') {
            temp3 = '15';
        } else if (temp1 == 'O') {
            temp3 = '16';
        } else if (temp1 == 'K') {
            temp3 = '26';
        }
        ins_cfi_set(dts_cfi_attr1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "1", "");
        ins_cfi_set(dts_cfi_attr2, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "2", "");
        ins_cfi_set(dts_cfi_attr3, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "3", "");
        ins_cfi_set(dts_cfi_attr4, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp3, temp1, temp2, "4", "");
        //alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        $c.stf.setObjectValue(label_attr1, "(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr2, "(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr3, "(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr4, "(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.fn_Change_cfi();
};
